/usr/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
names=['ClockCopy','ClockCopyHomog','DampedMultiplier','DampedNormsHomog','DriverParameters','FiniteGaussianMatrix','FiniteWick','FrequencyRow','GaussianHermite','GaussianScalarPowers','GramScalarAlgebra','H1Density','HermiteFock','HomogHypothesis']
for name in names:
 p=Path('lean/StratonovichHAMSecondMoment')/(name+'.lean'); ls=p.read_text().splitlines(); print('\\nFILE',p,'total',len(ls))
 active=False
 for i,l in enumerate(ls,1):
  if re.match(r'(theorem|lemma|def|noncomputable def|structure) ',l): active=bool(re.search(r'_paper|_completed',l))
  if l.startswith('variable'): print(f'{i}: {l}')
  if active:
   print(f'{i}: {l}')
   if ':=' in l: active=False
